<?php declare(strict_types=1);
require dirname(__DIR__,2).'/src/bootstrap.php';require dirname(__DIR__,2).'/native/bootstrap.php';
use Kulturhus\Verein\{Registry,Documents,DocumentChecks};
if(basename((string)getenv('KH_NATIVE_TEST_CONFIG'))!=='integrated-manager.json')throw new RuntimeException('Only isolated integrated browser fixture.');
$db=\Kulturhus\Native\TestSupport::db();$actor=$db->query('SELECT id FROM actors WHERE is_superuser=1 AND active=1 ORDER BY id LIMIT 1')->fetchColumn();if(!$actor)throw new RuntimeException('Synthetic browser admin absent.');
$runtime=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/integrated-manager-runtime';$manifest=$runtime.'/shared-calendar-documents.json';if(is_file($manifest)){echo "Existing isolated shared calendar/document fixture.\n";exit;}
$r=new Registry($db,$actor);$event=$r->saveAppointment(null,0,['title'=>'Gemeinsamer Kalendertermin','start'=>'2026-10-08T10:00','end'=>'2026-10-08T11:00','category'=>'verein'],[]);$check=(new DocumentChecks($db,$actor,$r))->save('',0,array_replace(DocumentChecks::defaults(),['title'=>'Gemeinsame Nachweisfrist','valid_until'=>'2026-10-08','review_on'=>'2026-10-08']));$docs=new Documents($db,$actor);$ids=[];for($i=0;$i<26;$i++)$ids[]=$docs->upload('Original-'.$i.'.txt','Gemeinsames Original '.$i,['title'=>'Gemeinsame Ablage '.sprintf('%02d',$i),'kind'=>'other','scope'=>'orga'],bin2hex(random_bytes(16)));$finance=$docs->upload('Finanzoriginal.txt','Unverändertes Finanzoriginal',['title'=>'Gemeinsame Finanzablage','kind'=>'receipt'],bin2hex(random_bytes(16)));
file_put_contents($manifest,json_encode(['event'=>$event,'check'=>$check,'documents'=>$ids,'finance'=>$finance],JSON_THROW_ON_ERROR));chmod($manifest,0600);echo "Isolated shared calendar/document fixture created.\n";
